from google.cloud import aiplatform

def get_vertex_ai_text_model_client(project_id: str, location: str):
    """Initializes and returns a Vertex AI text generation model client."""
    aiplatform.init(project=project_id, location=location)
    return aiplatform.gapic.PredictionServiceClient()

def get_vertex_ai_publisher_model_endpoint(model_name: str):
    """Returns the endpoint for a publisher model."""
    return f"projects/google/locations/us-central1/publishers/google/models/{model_name}"

def get_vertex_ai_embedding_model_client(project_id: str, location: str):
    """Initializes and returns a Vertex AI embedding model client."""
    aiplatform.init(project=project_id, location=location)
    return aiplatform.gapic.PredictionServiceClient()

import dataclasses
from typing import Any, Dict, List, Optional

@dataclasses.dataclass
class InferenceRequest:
    prompt: str
    model_id: str
    temperature: float = 0.7
    max_output_tokens: int = 1024

@dataclasses.dataclass
class InferenceResponse:
    text: str
    safety_attributes: Optional[Dict[str, Any]] = None

@dataclasses.dataclass
class EmbeddingRequest:
    text_entries: List[str]
    model_id: str

@dataclasses.dataclass
class EmbeddingResponse:
    embeddings: List[List[float]]


def normalize_vertex_ai_response(response: Any) -> InferenceResponse:
    """Normalizes a Vertex AI text generation response."""
    if response.predictions:
        # Assuming the first prediction contains the text
        text_content = response.predictions[0]["content"]
        safety_attributes = response.predictions[0].get("safetyAttributes")
        return InferenceResponse(text=text_content, safety_attributes=safety_attributes)
    return InferenceResponse(text="")

def normalize_vertex_ai_embedding_response(response: Any) -> EmbeddingResponse:
    """Normalizes a Vertex AI embedding response."""
    embeddings = []
    for prediction in response.predictions:
        if "embeddings" in prediction and "values" in prediction["embeddings"]:
            embeddings.append(prediction["embeddings"]["values"])
    return EmbeddingResponse(embeddings=embeddings)

import os
from google.cloud import aiplatform

def stream_completion(payload, config=None):
    config = config or {}
    project_id = config.get('project_id') or os.environ.get('GCP_PROJECT_ID')
    location = config.get('location') or os.environ.get('GCP_LOCATION', 'us-central1')
    model_id = config.get('model_id') or 'gemini-1.5-flash-001'

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GCP_PROJECT_ID environment variable.")

    aiplatform.init(project=project_id, location=location)

    model = aiplatform.GenerativeModel(model_id)

    prompt = payload.get('prompt', '')

    response_stream = model.generate_content(
        contents=prompt,
        stream=True,
        generation_config={
            "max_output_tokens": 1024,
            "temperature": 0.7,
        },
    )

    full_response_content = ""
    for chunk in response_stream:
        if chunk.candidates and chunk.candidates[0].content and chunk.candidates[0].content.parts:
            for part in chunk.candidates[0].content.parts:
                if part.text:
                    full_response_content += part.text

    return {'streamed_text': full_response_content}

import os
from google.cloud import aiplatform

def check_prompt_safety(payload, config=None):
    config = config or {}
    project_id = config.get('project_id') or os.environ.get('GCP_PROJECT_ID')
    location = config.get('location') or os.environ.get('GCP_LOCATION', 'us-central1')
    model_id = config.get('model_id') or 'gemini-1.5-flash-001'

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GCP_PROJECT_ID environment variable.")

    aiplatform.init(project=project_id, location=location)

    model = aiplatform.GenerativeModel(model_id)

    prompt = payload.get('prompt', '')

    # Vertex AI GenerativeModel automatically includes safety attributes in the response
    response = model.generate_content(contents=prompt)

    safety_attributes = None
    if response.candidates and response.candidates[0].safety_ratings:
        safety_attributes = [
            {"category": rating.category.name, "probability": rating.probability.name}
            for rating in response.candidates[0].safety_ratings
        ]

    return {
        'prompt': prompt,
        'safety_attributes': safety_attributes,
        'generated_content': response.candidates[0].content.parts[0].text if response.candidates and response.candidates[0].content and response.candidates[0].content.parts else ""
    }

import os
from google.cloud import translate_v2 as translate

def translate_text(payload, config=None):
    config = config or {}
    target_language = payload.get('target_language', 'en')
    text_to_translate = payload.get('text', '')

    if not text_to_translate:
        return {'translated_text': ''}

    # The Google Cloud client library for Translation will automatically use application default credentials
    # or the GOOGLE_APPLICATION_CREDENTIALS environment variable.
    # No explicit project ID is needed for basic translate_v2 usage if credentials are set up.
    translate_client = translate.Client()

    result = translate_client.translate(text_to_translate, target_language=target_language)

    return {
        'original_text': text_to_translate,
        'translated_text': result['translatedText'],
        'source_language': result['detectedSourceLanguage']
    }

import os
from google.cloud import texttospeech

def generate_spoken_brief(payload, config=None):
    config = config or {}
    text = payload.get('text', '')
    output_filename = payload.get('output_filename', 'spoken_brief.mp3')

    if not text:
        return {'audio_generated': False, 'message': 'No text provided for spoken brief.'}

    client = texttospeech.TextToSpeechClient()

    synthesis_input = texttospeech.SynthesisInput(text=text)

    # Select the voice and audio file type
    voice = texttospeech.VoiceSelectionParams(
        language_code="en-US", ssml_gender=texttospeech.SsmlVoiceGender.NEUTRAL
    )

    audio_config = texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.MP3
    )

    response = client.synthesize_speech(
        input=synthesis_input, voice=voice, audio_config=audio_config
    )

    # The response's audio_content is binary. Save it to a file.
    with open(output_filename, "wb") as out:
        out.write(response.audio_content)

    return {'audio_generated': True, 'output_file': output_filename, 'message': f'Audio content written to file {output_filename}'}
